@()        class UsefulService {}()        class NeedsService {          constructor(public service: UsefulService) {}        const injector =create({          providers: [            {provide: NeedsService, deps: [UsefulService]},            {provide: UsefulService, deps: []},          ],        });        expect(injector.get(NeedsService).service instanceof UsefulService).toBe(true);
